/*
 * 仅图标按钮的提示。在 Discourse 中，每个图标按钮都有
 * `title`（帖子操作、页头图标、弹窗的 ✕），浏览器会在
 * 鼠标停下时显示提示。在 Flarum 中这些按钮只有
 * `aria-label`；当它们不在核心的 `<Tooltip>` 内时，标签
 * 也会成为 `title`。
 */
import { extend } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
const pending = new Set();
let scheduled = false;
function sync(element) {
  if (!element.isConnected) return;
  const own = element.dataset.lcoyTitle;

  // 已经处理过且标签没变：跳过 jQuery 检查和文本读取。
  if (own && element.getAttribute('title') === own && element.getAttribute('aria-label') === own) return;

  // 核心的 <Tooltip> 已经显示提示（并把文本存在 jQuery 中）。
  const $ = window.$;
  if ($ && $(element).data('bs.tooltip')) return;
  const current = element.getAttribute('title');

  // 组件自带的标题优先。
  if (current && current !== own) return;
  const label = element.getAttribute('aria-label')?.trim();
  const iconOnly = !element.textContent?.trim();
  if (label && iconOnly) {
    if (current !== label) element.setAttribute('title', label);
    element.dataset.lcoyTitle = label;
  } else if (own) {
    element.removeAttribute('title');
    delete element.dataset.lcoyTitle;
  }
}
function flush() {
  scheduled = false;
  pending.forEach(sync);
  pending.clear();
}

/** 已处理且标签未变：不必在每次重绘时重新排队。 */
function synced(element) {
  const own = element.dataset.lcoyTitle;
  return !!own && own === element.getAttribute('aria-label');
}
export default function installTooltips() {
  // 等待一帧：按钮外层的 <Tooltip> 会在它之后挂载。
  extend(Button.prototype, ['oncreate', 'onupdate'], function () {
    const element = this.element;
    if (!element) return;

    // 长帖子滚动/打开编辑器会重绘所有按钮，这个集合曾是最大的
    // 重复工作来源。
    if (synced(element)) return;
    pending.add(element);
    if (!scheduled) {
      scheduled = true;
      requestAnimationFrame(flush);
    }
  });
}
flarum.reg.add('lcoy-roselle', 'forum/motion/tooltips', installTooltips);