/*
 * Horizon 中分类页的顶部：巨大的名称、描述，以及
 * 以白色卡片展示、带彩色方块符号的子分类。
 */
import Hero from 'flarum/forum/components/Hero';
import Link from 'flarum/common/components/Link';
import ItemList from 'flarum/common/utils/ItemList';
import { forumBool, t } from '../utils/settings';
import { categorySymbol, sortTags, tagSymbol, tagUrl } from '../utils/tags';
export default class CategoryHero extends Hero {
  className() {
    return 'LcoyCategoryHero';
  }
  style() {
    const color = this.attrs.model.color();
    return color ? {
      '--category-color': color
    } : undefined;
  }
  bodyItems() {
    const items = new ItemList();
    const tag = this.attrs.model;
    const description = tag.description();

    // 在 Flarum 中带图标的标签（二级标签）：图标在名称之前。
    const icon = tag.position() === null ? tagSymbol(tag, 'LcoyCategoryHero-icon') : null;
    items.add('title', m("h1", {
      className: "LcoyCategoryHero-title"
    }, icon, tag.name()), 100);
    if (description) {
      items.add('description', m("p", {
        className: "LcoyCategoryHero-description"
      }, description), 90);
    }
    const children = forumBool('lcoyCategoryHeroChildren', true) ? this.children() : [];
    if (children.length) {
      items.add('children', m("ul", {
        className: "LcoyCategoryHero-children",
        "aria-label": t('hero.subcategories')
      }, children.map(child => m("li", null, m(Link, {
        className: "LcoySubcategoryCard",
        href: tagUrl(child),
        style: child.color() ? {
          '--category-color': child.color()
        } : undefined
      }, m("span", {
        className: "LcoySubcategoryCard-tile"
      }, categorySymbol(child)), m("span", {
        className: "LcoySubcategoryCard-name"
      }, child.name()))))), 80);
    }
    return items;
  }
  children() {
    const children = this.attrs.model.children();

    // 子标签在加载标签时通过 `include=children` 到达；在此之前
    // （或对于标签）没有可列出的内容。
    if (!Array.isArray(children)) return [];
    return sortTags(children.filter(Boolean));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/list/CategoryHero', CategoryHero);