/*
 * Discourse 搜索：用搜索菜单（SearchMenu）取代打开核心
 * SearchModal 的按钮。页头的那个由 HeaderSearch
 * （shell/）绘制；这里加入欢迎横幅中的那个，在 Discourse 中
 * 它也是同一个 `search-menu`。
 */
import { extend } from 'flarum/common/extend';
import WelcomeBanner from '../list/WelcomeBanner';
import { forumBool } from '../utils/settings';
import SearchMenu from './SearchMenu';
export default function installSearchMenu() {
  extend(WelcomeBanner.prototype, 'bodyItems', function (items) {
    // 页头关闭了 Discourse 搜索时，横幅也保持 Flarum 的默认搜索。
    if (!forumBool('lcoyHeaderSearch', false)) return;
    if (!items.has('search')) return;
    items.setContent('search', m("div", {
      className: "LcoyWelcome-search"
    }, m(SearchMenu, {
      location: "welcome"
    })));
  });
}
flarum.reg.add('lcoy-roselle', 'forum/search', installSearchMenu);