/*
 * fof/upload：Discourse 编辑器中的 "上传中…" 提示（#file-uploading），
 * 带进度条。该扩展不提供百分比（请求只有
 * 一次），所以进度条是不确定的；上传结束或失败时它
 * 会消失。工具栏中的按钮由编辑器负责。
 */
import { extend } from 'flarum/common/extend';
import TextEditor from 'flarum/common/components/TextEditor';
import { t } from '../utils/settings';
import { thirdParty } from './settings';
export default function installUpload() {
  extend(TextEditor.prototype, 'oncreate', function () {
    this.uploader?.on?.('uploading', files => {
      this.lcoyUploadCount = files?.length || 1;
    });
  });
  extend(TextEditor.prototype, 'view', function (vdom) {
    if (!thirdParty.uploadProgress() || !this.uploader?.uploading || !vdom || !Array.isArray(vdom.children)) return;
    const count = this.lcoyUploadCount || 1;
    vdom.children.push(m("div", {
      className: "LcoyUploadProgress",
      role: "status",
      "aria-live": "polite"
    }, m("span", {
      className: "LcoyUploadProgress-label"
    }, t('thirdparty.upload.uploading', {
      count
    })), m("span", {
      className: "LcoyUploadProgress-bar",
      "aria-hidden": "true"
    }, m("span", {
      className: "LcoyUploadProgress-fill"
    }))));
  });
}
flarum.reg.add('lcoy-roselle', 'forum/thirdparty/upload', installUpload);