/*
 * Discourse 的会话菜单以当前登录者开头：头像、名字和
 * @用户名，点击进入资料页。Flarum 的菜单直接以“个人资料”开始；
 * 这里给它加上这个头部，其余条目（包括其他扩展的）
 * 保持原样。
 */
import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import SessionDropdown from 'flarum/forum/components/SessionDropdown';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import Separator from 'flarum/common/components/Separator';
export default function installSessionMenu() {
  extend(SessionDropdown.prototype, 'items', function (items) {
    const user = app.session.user;
    if (!user) return;
    const displayName = user.displayName();
    const username = user.username();
    items.add('lcoyIdentity', m(Link, {
      className: "LcoySessionIdentity",
      href: app.route.user(user)
    }, m(Avatar, {
      user: user,
      className: "LcoySessionIdentity-avatar"
    }), m("span", {
      className: "LcoySessionIdentity-names"
    }, m("span", {
      className: "LcoySessionIdentity-name"
    }, displayName), displayName !== username && m("span", {
      className: "LcoySessionIdentity-username"
    }, "@", username))), 200);
    items.add('lcoyIdentitySeparator', m(Separator, null), 150);
  });
}
flarum.reg.add('lcoy-roselle', 'forum/user/installSessionMenu', installSessionMenu);